package lk.ac.sliit.ridelink.ride.infrastructure.persistence.adapter;
import lk.ac.sliit.ridelink.ride.domain.enums.*; import lk.ac.sliit.ridelink.ride.domain.model.Ride; import lk.ac.sliit.ridelink.ride.infrastructure.persistence.repository.SpringDataRideRepository; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest; import org.springframework.context.annotation.Import; import org.springframework.test.context.ActiveProfiles; import java.math.BigDecimal; import java.util.UUID; import static org.junit.jupiter.api.Assertions.*;
@DataJpaTest @ActiveProfiles("test") @Import(RidePersistenceAdapter.class) class RidePersistenceAdapterTest {@Autowired RidePersistenceAdapter rides;@Autowired SpringDataRideRepository jpa;
 @Test void persistsDomainWithoutExposingEntity(){UUID passenger=UUID.randomUUID();Ride ride=Ride.request(UUID.randomUUID(),passenger,"A","B","Colombo",new BigDecimal("3.5"),VehicleType.BIKE,new BigDecimal("400"));Ride saved=rides.save(ride);assertAll(()->assertEquals(RideStatus.REQUESTED,saved.getStatus()),()->assertEquals(passenger,rides.findById(saved.getId()).orElseThrow().getPassengerId()),()->assertEquals(1,rides.findByPassengerId(passenger).size()));}
}
